using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public enum SwitchgearFamily{[EnumMember] gG,[EnumMember] aM,[EnumMember] AC20A,[EnumMember] AC20B,[EnumMember] AC21A,[EnumMember] AC21B,[EnumMember] AC22A,[EnumMember] AC22B,[EnumMember] AC23A,[EnumMember] AC23B}
[DataContract]public sealed class SwitchgearRating {
[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public SwitchgearFamily Family{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public PoleLayout Poles{get;set;}[DataMember]public double RatedA{get;set;}[DataMember]public double BreakingKA{get;set;}[DataMember]public double I2A{get;set;}[DataMember]public double IcwKA{get;set;}[DataMember]public double IcwSeconds{get;set;}[DataMember]public double IcmPeakKA{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Standard{get;set;}[DataMember]public string Sheet{get;set;}
public SwitchgearRating(){Manufacturer=Reference=Source=DataVersion=Standard=Sheet="";}
[Browsable(false)]public bool IsFuse{get{return Family==SwitchgearFamily.gG||Family==SwitchgearFamily.aM;}}
public SwitchgearRating Copy(){return (SwitchgearRating)MemberwiseClone();}
public void Validate(){foreach(string text in new[]{Manufacturer,Reference,Source,DataVersion,Standard,Sheet})if(String.IsNullOrWhiteSpace(text)||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Informe fabricante, referência, fonte, versão, norma declarada e ficha (até2000 caracteres).");if(!Enum.IsDefined(typeof(SwitchgearFamily),Family)||!Enum.IsDefined(typeof(PoleLayout),Poles))throw new InvalidDataException("Família/polos inválidos.");Project.Range(VoltageV,1,1e6,"tensão nominal");Project.Range(FrequencyHz,1,1000,"frequência nominal");Project.Range(RatedA,.001,1e9,"corrente nominal");foreach(double x in new[]{BreakingKA,I2A,IcwKA,IcwSeconds,IcmPeakKA})Project.Range(x,0,1e12,"capacidade nominal");if(IsFuse){if(BreakingKA<=0||IcwKA!=0||IcwSeconds!=0||IcmPeakKA!=0)throw new InvalidDataException("Fusível exige capacidade de interrupção; campos Icw/Icm devem ser zero.");}else if(BreakingKA!=0||I2A!=0||IcwKA<=0||IcwSeconds<=0||IcmPeakKA<=0)throw new InvalidDataException("Seccionador não interrompe curto: BreakingKA/I2A devem ser zero e Icw/tempo/Icm positivos.");}
}
[DataContract]public sealed class SwitchgearBinding {
[DataMember]public string Engine{get;set;}[DataMember]public SwitchgearRating Rating{get;set;}[DataMember]public SwitchgearFamily RequiredFamily{get;set;}[DataMember]public PoleLayout RequiredPoles{get;set;}[DataMember]public bool LoadSwitchingRequired{get;set;}[DataMember]public string ProtectingConfiguration{get;set;}
public void Validate(){if(Engine!=SwitchgearSelection.EngineId||Rating==null||!Enum.IsDefined(typeof(SwitchgearFamily),RequiredFamily)||!Enum.IsDefined(typeof(PoleLayout),RequiredPoles))throw new InvalidDataException("Vínculo de fusível/seccionador inválido ou revisão desconhecida.");Rating.Validate();if(ProtectingConfiguration==null||(ProtectingConfiguration!=""&&(ProtectingConfiguration.Length!=64||ProtectingConfiguration.Any(x=>!Uri.IsHexDigit(x)))))throw new InvalidDataException("Identidade da proteção do seccionador inválida.");}
}
public sealed partial class Circuit{[DataMember(Order=98),Browsable(false)]public SwitchgearBinding SwitchgearSelection{get;set;}}
public sealed class SwitchgearEvaluation{public string Status,Detail;}
public static class SwitchgearSelection {
public const string EngineId="cs-fusiveis-seccionadores-v1";
public const string Header="Manufacturer;Reference;Family;VoltageV;FrequencyHz;Poles;RatedA;BreakingKA;I2A;IcwKA;IcwSeconds;IcmPeakKA;Source;DataVersion;Standard;Sheet";
public static SwitchgearEvaluation Evaluate(Project p,Study study,Circuit c,SwitchgearBinding binding){if(binding==null)return new SwitchgearEvaluation{Status="Pendente",Detail="Fusível/seccionador não selecionado."};binding.Validate();var row=study.For(c);if(row==null)throw new InvalidDataException("Circuito fora do projeto.");var r=binding.Rating;bool fail=false,pending=false;var text=new StringBuilder("Motor "+EngineId+". "+(r.IsFuse?"Fusível":"Interruptor-seccionador")+": "+r.Manufacturer+" / "+r.Reference+"; família "+r.Family+"; "+r.VoltageV+" V AC; "+r.FrequencyHz+" Hz; "+BreakerSelection.PoleName(r.Poles)+"; In="+r.RatedA+" A. Fonte: "+r.Source+"; versão "+r.DataVersion+"; norma declarada "+r.Standard+"; ficha "+r.Sheet+".\r\n");
Compare(text,"Família, polos, tensão, frequência e ligação",r.Family==binding.RequiredFamily&&r.Poles==binding.RequiredPoles&&r.VoltageV==c.Voltage&&r.FrequencyHz==p.Frequency&&BreakerSelection.ValidTopology(row,binding.RequiredPoles),"Condição exata, sem substituir categorias por semelhança.",ref fail,ref pending);Compare(text,"Ib ≤ In",row.CurrentA<=r.RatedA,"Ib="+row.CurrentA.ToString("G8",CultureInfo.CurrentCulture)+" A.",ref fail,ref pending);
if(r.IsFuse){Compare(text,"Interrupção do fusível ≥ Ik nominal",row.FaultOriginKA.HasValue?(bool?)(r.BreakingKA>=row.FaultOriginKA.Value):null,"Capacidade="+r.BreakingKA+" kA; Ik nominal="+(row.FaultOriginKA.HasValue?row.FaultOriginKA.Value.ToString("G8",CultureInfo.CurrentCulture):"pendente")+" kA.",ref fail,ref pending);if(r.Family==SwitchgearFamily.gG){Compare(text,"In ≤ Iz",row.CorrectedAmpacityA.HasValue?(bool?)(r.RatedA<=row.CorrectedAmpacityA.Value):null,"Proteção de faixa completa; Iz corrigida do circuito.",ref fail,ref pending);Compare(text,"I2 ≤ 1,45 Iz",r.I2A>0&&row.CorrectedAmpacityA.HasValue?(bool?)(r.I2A<=1.45*row.CorrectedAmpacityA.Value):null,"I2 declarado da ficha; não inferir só pela família.",ref fail,ref pending);}else{pending=true;text.AppendLine("Pendente: aM é de faixa parcial; requer proteção de sobrecarga/coordenacão do motor separada. Não aprova sobrecarga por In do fusível.");}text.AppendLine("Seleção do conjunto de fusíveis/porta-fusíveis e elementos de neutro conforme configuração declarada; verificar compatibilidade física, seccionamento e energia passante do fabricante.");}
else{bool isolationOnly=r.Family==SwitchgearFamily.AC20A||r.Family==SwitchgearFamily.AC20B;Compare(text,"Categoria para manobra solicitada",!binding.LoadSwitchingRequired||!isolationOnly,"AC20 exige operação sem carga; categoria exigida é declarada pelo projetista.",ref fail,ref pending);bool protectionKnown=c.Protection.BreakerSnapshot!=null&&binding.ProtectingConfiguration!=""&&String.Equals(binding.ProtectingConfiguration,Coordination.ProtectionConfiguration(c),StringComparison.OrdinalIgnoreCase);string ignored;protectionKnown=protectionKnown&&BreakerSelection.Applicable(p,row,c.Protection.BreakerSnapshot,out ignored);Compare(text,"Proteção contra curto identificada",protectionKnown&&row.FaultOriginKA.HasValue?(bool?)(c.Protection.BreakingCapacityKA>=row.FaultOriginKA.Value):null,"O seccionador está a jusante da proteção identificada neste circuito; ele não elimina a falta.",ref fail,ref pending);Compare(text,"Icw e duração",protectionKnown&&row.FaultOriginKA.HasValue&&c.Protection.DisconnectSeconds>0?(bool?)(row.FaultOriginKA.Value<=r.IcwKA&&c.Protection.DisconnectSeconds<=r.IcwSeconds):null,"Icw="+r.IcwKA+" kA por "+r.IcwSeconds+" s; tempo de eliminação declarado="+c.Protection.DisconnectSeconds+" s; sem extrapolação I²t para corrente maior.",ref fail,ref pending);Compare(text,"Icm ≥ pico nominal disponível",row.FaultOriginDynamics!=null?(bool?)(r.IcmPeakKA>=row.FaultOriginDynamics.PeakKA):null,"Icm="+r.IcmPeakKA+" kA pico; não é capacidade de interrupção. Modelo de pico R-L disponível não comprova extremo normativo.",ref fail,ref pending);text.AppendLine("O seccionador não protege contra sobrecarga/curto. A proteção e o cabo mantêm suas verificações próprias. Não se presume limitação de corrente ou associação certificada com a proteção.");}
text.AppendLine("Resultado nominal condicionado às hipóteses da rede e dados declarados. Sem certificação normativa, Ik máximo, energia passante completa, manobras/repetições, condições ambientais ou coordenação global.");return new SwitchgearEvaluation{Status=fail?"Não atende":pending?"Dados incompletos":"Atende comparações nominais",Detail=text.ToString()};}
static void Compare(StringBuilder text,string rule,bool? pass,string detail,ref bool fail,ref bool pending){if(!pass.HasValue)pending=true;else if(!pass.Value)fail=true;text.AppendLine((pass.HasValue?(pass.Value?"Atende":"Não atende"):"Pendente")+": "+rule+". "+detail);}
public static SwitchgearBinding Candidate(Circuit circuit,SwitchgearRating rating,SwitchgearFamily family,PoleLayout poles,bool loadSwitching){if(circuit==null||rating==null)throw new InvalidDataException("Dados ausentes.");return new SwitchgearBinding{Engine=EngineId,Rating=rating.Copy(),RequiredFamily=family,RequiredPoles=poles,LoadSwitchingRequired=loadSwitching,ProtectingConfiguration=Coordination.ProtectionConfiguration(circuit)};}
public static void Apply(Project p,Circuit c,SwitchgearRating rating,SwitchgearFamily family,PoleLayout poles,bool loadSwitching){var binding=Candidate(c,rating,family,poles,loadSwitching);var result=Evaluate(p,Engineering.Analyze(p),c,binding);if(result.Status=="Não atende")throw new InvalidDataException("Nenhuma alteração: "+result.Detail);c.SwitchgearSelection=binding;}
static double Number(string text){double x;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!Double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out x)||Double.IsNaN(x)||Double.IsInfinity(x))throw new InvalidDataException("Número inválido.");return x;}
static T EnumValue<T>(string text){try{var x=(T)Enum.Parse(typeof(T),text,true);if(Enum.IsDefined(typeof(T),x))return x;}catch{}throw new InvalidDataException("Família/polos inválidos.");}
static void ValidateRows(List<SwitchgearRating> rows){if(rows.Count>100000)throw new InvalidDataException("Tabela excede100000 itens.");var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var r in rows){if(r==null)throw new InvalidDataException("Linha ausente.");r.Validate();string key=String.Join("\0",new[]{r.Manufacturer.Trim(),r.Reference.Trim(),r.Family.ToString(),r.Poles.ToString(),r.VoltageV.ToString("R",CultureInfo.InvariantCulture),r.FrequencyHz.ToString("R",CultureInfo.InvariantCulture)});if(!keys.Add(key))throw new InvalidDataException("Condição de dispositivo duplicada.");}}
public static List<SwitchgearRating> Import(string file){if(new FileInfo(file).Length>32L*1024*1024)throw new InvalidDataException("Arquivo excede32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count==0||rows.Count>100001||String.Join(";",rows[0])!=Header)throw new InvalidDataException("Cabeçalho/tamanho incompatível.");var list=new List<SwitchgearRating>();for(int i=1;i<rows.Count;i++){try{var r=rows[i];if(r.Length!=16)throw new InvalidDataException("Esperadas16 colunas.");list.Add(new SwitchgearRating{Manufacturer=r[0],Reference=r[1],Family=EnumValue<SwitchgearFamily>(r[2]),VoltageV=Number(r[3]),FrequencyHz=Number(r[4]),Poles=EnumValue<PoleLayout>(r[5]),RatedA=Number(r[6]),BreakingKA=Number(r[7]),I2A=Number(r[8]),IcwKA=Number(r[9]),IcwSeconds=Number(r[10]),IcmPeakKA=Number(r[11]),Source=r[12],DataVersion=r[13],Standard=r[14],Sheet=r[15]});}catch(Exception ex){throw new InvalidDataException("Registro "+(i+1)+": "+ex.Message,ex);}}ValidateRows(list);return list;}
static string Quote(string text){return "\""+text.Replace("\"","\"\"")+"\"";}
public static void Export(IEnumerable<SwitchgearRating> rows,string file){var list=rows.ToList();ValidateRows(list);string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string tmp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(Header+"\r\n");using(var w=new StreamWriter(tmp,false,new UTF8Encoding(true))){w.WriteLine(Header);foreach(var r in list){string line=String.Join(";",new[]{r.Manufacturer,r.Reference,r.Family.ToString(),r.VoltageV.ToString("R",CultureInfo.InvariantCulture),r.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),r.Poles.ToString(),r.RatedA.ToString("R",CultureInfo.InvariantCulture),r.BreakingKA.ToString("R",CultureInfo.InvariantCulture),r.I2A.ToString("R",CultureInfo.InvariantCulture),r.IcwKA.ToString("R",CultureInfo.InvariantCulture),r.IcwSeconds.ToString("R",CultureInfo.InvariantCulture),r.IcmPeakKA.ToString("R",CultureInfo.InvariantCulture),r.Source,r.DataVersion,r.Standard,r.Sheet}.Select(Quote));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Tabela excede32 MiB; destino preservado.");w.WriteLine(line);}}if(File.Exists(full))File.Replace(tmp,full,full+".bak");else File.Move(tmp,full);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
}
}
